{"code":"def transform(g):
    # The three-by-three colour samples act as a palette; the middle sample
    # is propagated along the marked tracks (the other visible propagated
    # colour is the first sample).
    mid=g[0][4]
    out=[[7]*11 for _ in range(13)]
    # arrangement of the propagated tiles
    tiles=[(0,1,5),(3,0,mid),(3,8,5),(5,4,mid),(7,1,5),(8,7,mid)]
    for r,c,col in tiles:
        for i in range(3):
            for j in range(3):
                if 0<=r+i<13 and 0<=c+j<11: out[r+i][c+j]=col
    return out"}

